{
  "steps": [
    {
      "step_id": "cb_step_1",
      "title": "Choose the input CT scan",
      "simple": "Select the pelvic CT volume in the Input CT Volume section.",
      "detailed": "This CT scan is the source for all subsequent bone segmentation and fracture planning. Choose the volume that contains the patient's pelvis so the rest of the workflow analyzes the correct anatomy."
    },
    {
      "step_id": "cb_step_2",
      "title": "Segment the pelvis",
      "simple": "Click the 'Run Step 1: Segment Pelvis' button.",
      "detailed": "This creates a 3D model of the intact pelvic bone from the CT scan. It is the foundation for generating a reduction template and for comparing the fractured bone against the expected pelvic shape."
    },
    {
      "step_id": "cb_step_3",
      "title": "Center the 3D view",
      "simple": "Click the 'Center view' button in the 3D view.",
      "detailed": "Centering the view keeps the pelvis in the middle of the 3D window after segmentation. This makes subsequent steps, such as checking fracture segments, easier by giving you a stable, balanced vantage point."
    },
    {
      "step_id": "cb_step_4",
      "title": "Segment the fractures",
      "simple": "Click the 'Run Step 2: Segment Fractures' button.",
      "detailed": "This separates the fractured pelvic fragments from the intact bone. The resulting fragment segments are what later steps will align, reduce, and use to plan screw fixation."
    },
    {
      "step_id": "cb_step_5",
      "title": "Choose which pieces count as separate fragments",
      "simple": "In the untick section, turn off the segments that should not be treated as separate pieces.",
      "detailed": "Automatic fracture segmentation may create small or unimportant pieces that should not be handled as independent fragments. Unticking them removes them from the fragment list, so reduction and screw planning focus on the fragments that matter for surgery."
    },
    {
      "step_id": "cb_step_6",
      "title": "Check whether manual splitting is needed",
      "simple": "Choose Yes if a fragment that should be separated was left connected, otherwise choose No.",
      "detailed": "If two bone pieces are still fused and need to be treated separately, a manual cut is required before reduction. Answering Yes opens the manual separation tool; answering No proceeds directly to template generation."
    },
    {
      "step_id": "cb_step_7",
      "title": "Start manual separation",
      "simple": "Click the 'Manually separate' button.",
      "detailed": "This activates the cutting tool so you can draw a plane through the bone at the place that needs to be split. The plane you place in the next step will divide the fragment."
    },
    {
      "step_id": "cb_step_8",
      "title": "Place the cutting plane",
      "simple": "Position and rotate the cutting plane along the fracture line, then click Done.",
      "detailed": "This plane defines exactly where the fused fragment will be split. Align it with the natural fracture surface so the resulting edges mate well during reduction."
    },
    {
      "step_id": "cb_step_9",
      "title": "Confirm the separation",
      "simple": "Click the 'Confirm separation' button.",
      "detailed": "This applies the plane you placed and actually splits the fragment. After confirmation, the fragment list is updated and the workflow can continue to template generation."
    },
    {
      "step_id": "cb_step_10",
      "title": "Generate the reduction template",
      "simple": "Click the 'Run Step 3: Generate template' button.",
      "detailed": "A template is created from the segmented pelvis as an anatomical reference for the desired reduction. It guides the later step that registers and reduces the fractured fragments back toward a normal pelvic shape."
    },
    {
      "step_id": "cb_step_11",
      "title": "Decide whether to adjust the template",
      "simple": "Choose Yes if you want to fine-tune the template, otherwise choose No.",
      "detailed": "The automatically generated template may need small positioning or shape corrections before it is used for reduction. Choosing Yes lets you select and adjust templates; choosing No continues straight to fragment registration and reduction."
    },
    {
      "step_id": "cb_step_12",
      "title": "Choose the template to adjust",
      "simple": "Select the template that needs adjustment in the Template box.",
      "detailed": "If more than one template exists, pick the one you want to fine-tune before applying changes. This keeps adjustments targeted to the correct anatomical reference."
    },
    {
      "step_id": "cb_step_13",
      "title": "Adjust the view",
      "simple": "Rotate, zoom, or pan the 3D view to see the selected template clearly.",
      "detailed": "This step only changes your viewpoint so you can inspect the selected template from the best angle. Use the mouse to rotate and zoom; no point or marker needs to be placed."
    },
    {
      "step_id": "cb_step_14",
      "title": "Choose whether more templates need adjustment",
      "simple": "Choose Yes to adjust another template, or No to finish template adjustment.",
      "detailed": "Repeating the template adjustment keeps the anatomical reference aligned with your planning goals. When every template is satisfactory, choose No and apply the changes in the next step."
    },
    {
      "step_id": "cb_step_15",
      "title": "Apply the template adjustment",
      "simple": "Click the 'Apply template adjustment' button.",
      "detailed": "This commits the template changes and updates the reduction reference. Applying the adjustments ensures the next registration step uses the corrected template."
    },
    {
      "step_id": "cb_step_16",
      "title": "Register and reduce the fragments",
      "simple": "Click the 'Run Step 4: Register _Reduce' button.",
      "detailed": "This aligns the fractured pelvic fragments with the template and brings them into a reduced position. The result is a preliminary fracture reduction that can be manually refined before screw planning."
    },
    {
      "step_id": "cb_step_17",
      "title": "Decide whether to refine fragments manually",
      "simple": "Choose Yes if you want to adjust the reduced fragments, otherwise choose No.",
      "detailed": "After automatic reduction, some fragments may still need small positional or rotational corrections to achieve a better fit. Choosing Yes allows you to select and fine-tune fragments; choosing No proceeds to screw planning."
    },
    {
      "step_id": "cb_step_18",
      "title": "Choose the fragment to adjust",
      "simple": "Select the fragment that needs adjustment in the Fragment box.",
      "detailed": "Picking a specific fragment focuses your adjustments on only that bone piece. This is useful when one fragment is not aligned well after the automatic reduction."
    },
    {
      "step_id": "cb_step_19",
      "title": "Adjust the view",
      "simple": "Rotate, zoom, or pan the 3D view to see the selected fragment clearly.",
      "detailed": "This step only changes your viewpoint so you can inspect the selected fragment's position. Use the mouse to rotate and zoom; no point or marker needs to be placed."
    },
    {
      "step_id": "cb_step_20",
      "title": "Choose whether more fragments need adjustment",
      "simple": "Choose Yes to adjust another fragment, or No to finish fragment adjustments.",
      "detailed": "Checking each fragment from a clear angle helps ensure the reduced pelvis is anatomically correct. When all fragments are satisfactory, choose No and apply the adjustments."
    },
    {
      "step_id": "cb_step_21",
      "title": "Apply the fragment adjustments",
      "simple": "Click the 'Apply adjustments' button.",
      "detailed": "This commits the manual fragment corrections and updates the reduced pelvis model. The finalized reduction is then used for screw trajectory planning."
    },
    {
      "step_id": "cb_step_22",
      "title": "Plan the screws",
      "simple": "Click the 'Run Step 5: Plan Screws' button.",
      "detailed": "This plans screw trajectories for fixing the reduced pelvic fragments. The resulting plans show proposed screw positions and directions, which you can inspect and refine before surgery."
    },
    {
      "step_id": "cb_step_23",
      "title": "Decide whether to edit screw trajectories",
      "simple": "Choose Yes if you want to adjust the planned screw paths, otherwise choose No.",
      "detailed": "Automatic screw planning may not fit every patient's anatomy. Choosing Yes lets you review and edit the trajectories; choosing No completes the workflow with the automatically planned screws."
    },
    {
      "step_id": "cb_step_24",
      "title": "Adjust the view",
      "simple": "Rotate, zoom, or pan the 3D view to see the screw trajectories clearly.",
      "detailed": "This step only changes your viewpoint so you can inspect the planned screw trajectories from the best angle. Use the mouse to rotate and zoom; no point or marker needs to be placed."
    },
    {
      "step_id": "cb_step_25",
      "title": "Regenerate the screws from edited trajectories",
      "simple": "Click the 'Regenerate screws from edited lines' button.",
      "detailed": "This updates the screw plans to match any edits made to the trajectory lines. After regeneration, the displayed screws reflect the final planned paths."
    }
  ]
}
